/* JAH demo program — JAH-SATL-000001 */
/* Sputnik 1 orbit demo */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("ORBIT DEMO — Sputnik 1 (1957-001B)");
var mu=398600.4418; /* km^3/s^2 */
var alt=577;
var a=6371+alt;
var T=2*Math.PI*Math.sqrt(Math.pow(a,3)/mu);
console.log("mean altitude: "+alt+" km");
console.log("orbital period: "+(T/60).toFixed(2)+" minutes ("+(T/3600).toFixed(2)+" hours)");
console.log("orbit: LEO | status: Decayed 1958-01-04");

